import pytest

from llm.model_gateway import ModelGateway


class FakeAdapter:

    def __init__(self, label):
        self.label = label
        self.calls = []

    def generate(self, **kwargs):

        self.calls.append(kwargs)

        return {
            "status": "GENERATED_VERIFIED",
            "response": f"Generated by {self.label}.",
        }


def verified_result():
    return {
        "principal": 1_000_000,
        "annual_rate": 8.5,
        "tenure_months": 240,
        "monthly_emi": 8678.23,
        "total_payment": 2082775.76,
        "total_interest": 1082775.76,
    }


def test_register_and_default_model():

    adapter = FakeAdapter("model-a")

    gateway = ModelGateway(
        default_model="model-a"
    )

    gateway.register(
        "model-a",
        adapter,
        capabilities=["response_generation"],
    )

    result = gateway.generate(
        user_text="Calculate EMI",
        intent="EMI_QUERY",
        verified_result=verified_result(),
        source="deterministic_finance_engine",
    )

    assert result["model_id"] == "model-a"
    assert result["response"] == "Generated by model-a."
    assert len(adapter.calls) == 1


def test_explicit_model_selection():

    adapter_a = FakeAdapter("model-a")
    adapter_b = FakeAdapter("model-b")

    gateway = ModelGateway(
        default_model="model-a"
    )

    gateway.register("model-a", adapter_a)
    gateway.register("model-b", adapter_b)

    result = gateway.generate(
        user_text="Calculate EMI",
        intent="EMI_QUERY",
        verified_result=verified_result(),
        source="deterministic_finance_engine",
        model_id="model-b",
    )

    assert result["model_id"] == "model-b"
    assert result["response"] == "Generated by model-b."

    assert len(adapter_a.calls) == 0
    assert len(adapter_b.calls) == 1


def test_set_default_model():

    adapter_a = FakeAdapter("model-a")
    adapter_b = FakeAdapter("model-b")

    gateway = ModelGateway(
        default_model="model-a"
    )

    gateway.register("model-a", adapter_a)
    gateway.register("model-b", adapter_b)

    gateway.set_default("model-b")

    result = gateway.generate(
        user_text="Hello",
        intent="SUPPORT_REQUEST",
        verified_result={},
        source="support_system",
    )

    assert gateway.default_model == "model-b"
    assert result["model_id"] == "model-b"


def test_unknown_model_fails_safely():

    gateway = ModelGateway(
        default_model="missing-model"
    )

    with pytest.raises(ValueError):
        gateway.generate(
            user_text="Hello",
            intent="SUPPORT_REQUEST",
            verified_result={},
            source="support_system",
        )


def test_capabilities_are_preserved():

    adapter = FakeAdapter("model-a")

    gateway = ModelGateway()

    gateway.register(
        "model-a",
        adapter,
        capabilities=[
            "financial_reasoning",
            "response_generation",
        ],
    )

    assert gateway.capabilities("model-a") == [
        "financial_reasoning",
        "response_generation",
    ]


def test_available_models_are_sorted():

    gateway = ModelGateway()

    gateway.register(
        "z-model",
        FakeAdapter("z"),
    )

    gateway.register(
        "a-model",
        FakeAdapter("a"),
    )

    assert gateway.available_models() == [
        "a-model",
        "z-model",
    ]
